   157→    // 결과 집합에서 특정 행 조회
   158→    func (rs: *ResultSet) result_set_get_row(idx: i32) -> (ResultRow, i32) {
   159→        // 범위 확인
   160→        if idx < 0 || idx >= rs.row_count {
   161→            let empty_row = ResultRow{
   162→                int_vals:  make([i64], 0),
   163→                str_vals:  make([string], 0),
   164→                bool_vals: make([bool], 0),
   165→                col_count: 0,
   166→            };
   167→            return (empty_row, RESULT_ERR_EMPTY);
   168→        }
   169→
   170→        return (rs.rows[idx], RESULT_OK);
   171→    }
