   219→    // 결과 집합의 행 개수 반환
   220→    func (rs: *ResultSet) result_set_get_row_count() -> i32 {
   221→        return rs.row_count;
   222→    }
   223→
   224→    // 결과 집합의 컬럼 개수 반환
   225→    func (rs: *ResultSet) result_set_get_col_count() -> i32 {
