   229→    // === 디버그 및 출력 함수 ===
   230→
   231→    // ResultSet을 문자열로 변환 (디버깅용)
   232→    // 형식: "Row 0: [val1, val2, ...]\nRow 1: ..."
   233→    func (rs: *ResultSet) result_set_to_string() -> string {
   234→        if rs.row_count == 0 {
   235→            return "[Empty ResultSet]";
   236→        }
   237→
   238→        let output = "";
   239→        let i = 0;
   240→
   241→        for i = 0; i < rs.row_count; i = i + 1 {
   242→            let row = rs.rows[i];
   243→
   244→            // "Row i: ["
   245→            output = output + "Row " + i32_to_str(i) + ": [";
   246→
   247→            // 각 컬럼값 추가 (첫 5개만 표시하는 제약)
   248→            let j = 0;
   249→            for j = 0; j < row.col_count; j = j + 1 {
   250→                if j > 0 {
   251→                    output = output + ", ";
   252→                }
   253→
   254→                // int_vals에서 값 출력
   255→                if j < MAX_RESULT_COLS {
   256→                    let val = row.int_vals[j];
   257→                    output = output + i64_to_str(val);
   258→                }
   259→            }
   260→
   261→            output = output + "]\n";
   262→        }
   263→
   264→        return output;
   265→    }
