     2→// FreeLang Query Context 모듈 - 쿼리 실행 컨텍스트
     3→// ============================================================================
     4→// 목표: 쿼리 실행 중 임시 값, 세션 정보, 성능 메트릭을 관리하는 컨텍스트
     5→// 원리:
     6→//   1. TempValue: 변수 ID → 임시 값 매핑 (정수/문자열 dual-type)
     7→//   2. QueryContext: 세션, 쿼리 ID, 임시 값 배열, 타이밍 메타데이터
     8→//   3. var_id 검색: for 루프로 is_used 플래그 추적하며 탐색
     9→// 구조:
    10→//   - 상수 정의 (에러 코드 150-151, 제한값)
    11→//   - TempValue, QueryContext 구조체
    12→//   - 컨텍스트 생성/정리
    13→//   - 임시 값 set/get (정수/문자열)
    14→//   - 통계 조회
    15→// ============================================================================
    16→
    17→module query_context {
    18→    // === 에러 코드 ===
    19→    const QCTX_OK:           i32 = 0;
    20→    const QCTX_ERR_NOTFOUND: i32 = 150;
    21→    const QCTX_ERR_FULL:     i32 = 151;
    22→
    23→    // === 제한값 ===
    24→    const MAX_TEMP_VALUES: i32 = 256;
    25→
    26→    // === 데이터 구조체 ===
    27→
    28→    // 임시 값 슬롯 (정수/문자열 dual-type)
    29→    struct TempValue {
    30→        var_id:  i32;
    31→        val_int: i64;
    32→        val_str: string;
    33→        is_used: bool;
    34→    }
    35→
    36→    // 쿼리 실행 컨텍스트
    37→    struct QueryContext {
    38→        session_id:  i64;
    39→        query_id:    i64;
    40→        temp_values: [TempValue];
    41→        temp_count:  i32;
    42→        start_ts:    i64;
    43→        step_count:  i32;
    44→    }
    45→
    46→    // === 컨텍스트 생성/정리 ===
    47→
    48→    // 새 쿼리 컨텍스트 생성
    49→    func query_context_new(session_id: i64) -> QueryContext {
    50→        var qc: QueryContext;
    51→        qc.session_id = session_id;
    52→        qc.query_id = 0;
    53→        qc.temp_values = make([TempValue], MAX_TEMP_VALUES);
    54→        qc.temp_count = 0;
    55→        qc.start_ts = 1000; // 카운터 기반 시간 (초기값)
    56→        qc.step_count = 0;
    57→        return qc;
    58→    }
    59→
    60→    // === 임시 값 관리 ===
    61→
    62→    // 임시 정수 값 설정 (기존이면 업데이트, 없으면 추가)
    63→    func (qc: *QueryContext) query_context_set_temp_int(var_id: i32, val: i64) -> i32 {
    64→        // 기존 var_id 검색
    65→        var i: i32 = 0;
    66→        while i < qc.temp_count {
    67→            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
    68→                // 기존 슬롯 업데이트
    69→                qc.temp_values[i].val_int = val;
    70→                return QCTX_OK;
    71→            }
    72→            i = i + 1;
    73→        }
    74→
    75→        // 새 슬롯 추가
    76→        if qc.temp_count >= MAX_TEMP_VALUES {
    77→            return QCTX_ERR_FULL;
    78→        }
    79→
    80→        qc.temp_values[qc.temp_count].var_id = var_id;
    81→        qc.temp_values[qc.temp_count].val_int = val;
    82→        qc.temp_values[qc.temp_count].val_str = "";
    83→        qc.temp_values[qc.temp_count].is_used = true;
    84→        qc.temp_count = qc.temp_count + 1;
    85→
    86→        return QCTX_OK;
    87→    }
    88→
    89→    // 임시 문자열 값 설정 (기존이면 업데이트, 없으면 추가)
    90→    func (qc: *QueryContext) query_context_set_temp_str(var_id: i32, val: string) -> i32 {
    91→        // 기존 var_id 검색
    92→        var i: i32 = 0;
    93→        while i < qc.temp_count {
    94→            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
    95→                // 기존 슬롯 업데이트
    96→                qc.temp_values[i].val_str = val;
    97→                return QCTX_OK;
    98→            }
    99→            i = i + 1;
   100→        }
   101→
   102→        // 새 슬롯 추가
   103→        if qc.temp_count >= MAX_TEMP_VALUES {
   104→            return QCTX_ERR_FULL;
   105→        }
   106→
   107→        qc.temp_values[qc.temp_count].var_id = var_id;
   108→        qc.temp_values[qc.temp_count].val_int = 0;
   109→        qc.temp_values[qc.temp_count].val_str = val;
   110→        qc.temp_values[qc.temp_count].is_used = true;
   111→        qc.temp_count = qc.temp_count + 1;
   112→
   113→        return QCTX_OK;
   114→    }
   115→
   116→    // 임시 정수 값 조회
   117→    func (qc: *QueryContext) query_context_get_temp_int(var_id: i32) -> (i64, i32) {
   118→        var i: i32 = 0;
   119→        while i < qc.temp_count {
   120→            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
   121→                return (qc.temp_values[i].val_int, QCTX_OK);
   122→            }
   123→            i = i + 1;
   124→        }
   125→        return (0, QCTX_ERR_NOTFOUND);
   126→    }
   127→
   128→    // 임시 문자열 값 조회
   129→    func (qc: *QueryContext) query_context_get_temp_str(var_id: i32) -> (string, i32) {
   130→        var i: i32 = 0;
   131→        while i < qc.temp_count {
   132→            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
   133→                return (qc.temp_values[i].val_str, QCTX_OK);
   134→            }
   135→            i = i + 1;
   136→        }
   137→        return ("", QCTX_ERR_NOTFOUND);
   138→    }
   139→
   140→    // === 컨텍스트 상태 관리 ===
   141→
   142→    // 모든 임시 값 초기화
   143→    func (qc: *QueryContext) query_context_clear_temps() -> i32 {
   144→        var i: i32 = 0;
   145→        while i < qc.temp_count {
   146→            qc.temp_values[i].var_id = 0;
   147→            qc.temp_values[i].val_int = 0;
   148→            qc.temp_values[i].val_str = "";
   149→            qc.temp_values[i].is_used = false;
   150→            i = i + 1;
   151→        }
   152→        qc.temp_count = 0;
   153→        return QCTX_OK;
   154→    }
   155→
   156→    // 쿼리 실행 종료 (메트릭 기록)
   157→    func (qc: *QueryContext) query_context_end() -> i32 {
   158→        qc.step_count = qc.step_count + 1;
   159→        return QCTX_OK;
   160→    }
   161→
   162→    // === 통계 조회 ===
   163→
   164→    // 컨텍스트 상태 문자열 표현
   165→    func (qc: *QueryContext) query_context_stats() -> string {
   166→        var result: string = "";
   167→        result = result + "QueryContext {session_id: ";
   168→        result = result + string(qc.session_id);
   169→        result = result + ", query_id: ";
   170→        result = result + string(qc.query_id);
   171→        result = result + ", temp_count: ";
   172→        result = result + string(qc.temp_count);
   173→        result = result + ", step_count: ";
   174→        result = result + string(qc.step_count);
   175→        result = result + "}";
   176→        return result;
   177→    }
   178→}
